    rdfs:comment "Relates a resource to an earlier resource that precedes it in a relevant sequence or historical lineage."@en ;
    rdfs:domain rdfs:Resource ;
    rdfs:range rdfs:Resource .

:providesFeedbackCapability a owl:ObjectProperty ;
    rdfs:label "provides feedback capability"@en ;
    rdfs:comment "Identifies a FeedbackCapability provided by a resource, such as visual, audio, or haptic feedback."@en ;
    rdfs:domain rdfs:Resource ;
    rdfs:range :FeedbackCapability .

:publishedBy a owl:ObjectProperty ;
    rdfs:label "published by"@en ;
    rdfs:comment "Identifies an Organization that published a VideoGame or GameRelease; use :PublisherRole in a qualified PROV association when the role needs explicit qualification."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :Organization ;
    rdfs:subPropertyOf :hasParticipatingOrganization,
        schema:publisher .

:ratingCode a owl:DatatypeProperty ;
    rdfs:label "rating code"@en ;
    rdfs:comment "Records the code assigned to a ContentRating by its RatingSystem, such as an age or classification code."@en ;
    rdfs:domain :ContentRating ;
    rdfs:range xsd:string .

:releaseDate a owl:DatatypeProperty ;
    rdfs:label "release date"@en ;
    rdfs:comment "Records the formal release date of a GameRelease; it specializes dcterms:issued and schema:datePublished."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range xsd:date ;
    rdfs:subPropertyOf dcterms:issued,
        schema:datePublished .

:requiresInputDevice a owl:ObjectProperty ;
    rdfs:label "requires input device"@en ;
    rdfs:comment "Identifies an InputDevice required to use a GameRelease."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :InputDevice ;
    rdfs:subPropertyOf :supportsInputDevice .

:requiresOnlineService a owl:ObjectProperty ;
    rdfs:label "requires online service"@en ;
    rdfs:comment "Identifies an OnlineService that is required to access or use a GameResource."@en ;
    rdfs:domain :GameResource ;
    rdfs:range :OnlineService ;
    rdfs:subPropertyOf :accessibleViaOnlineService .

:supportsDisplayTechnology a owl:ObjectProperty ;
    rdfs:label "supports display technology"@en ;
    rdfs:comment "Identifies a DisplayTechnology supported by a VideoGame or GameRelease."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :DisplayTechnology .

:supportsMultiplayerConnectivity a owl:ObjectProperty ;
    rdfs:label "supports multiplayer connectivity"@en ;
    rdfs:comment "Associates a VideoGame or GameRelease with a supported multiplayer connectivity mode."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :MultiplayerConnectivityMode .

:supportsMultiplayerStyle a owl:ObjectProperty ;
    rdfs:label "supports multiplayer style"@en ;
    rdfs:comment "Associates a VideoGame or GameRelease with a supported multiplayer style."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :MultiplayerStyle .

:supportsOutputDevice a owl:ObjectProperty ;
    rdfs:label "supports output device"@en ;
    rdfs:comment "Identifies an OutputDevice through which a VideoGame or GameRelease can present output."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :OutputDevice .

:usedMicrophoneForInGameCommunication a owl:ObjectProperty ;
    rdfs:label "used microphone for in-game communication"@en ;
    rdfs:comment "Identifies a Microphone used during a GameplaySession for in-game communication."@en ;
    rdfs:domain :GameplaySession ;
    rdfs:range :Microphone ;
    rdfs:subPropertyOf :usedInputDevice .

:usedWebcamForLivestreaming a owl:ObjectProperty ;
    rdfs:label "used webcam for livestreaming"@en ;
    rdfs:comment "Identifies a Webcam used during a GameplaySession for livestreaming."@en ;
    rdfs:domain :GameplaySession ;
    rdfs:range :Webcam ;
    rdfs:subPropertyOf :usedInputDevice .

:userCreated a owl:DatatypeProperty ;
    rdfs:label "user created"@en ;
    rdfs:comment "Indicates whether game-related content was created by users rather than as official first-party or licensed content."@en ;
    rdfs:domain :GameRelatedContent ;
    rdfs:range xsd:boolean .

:validInRegion a owl:ObjectProperty ;
    rdfs:label "valid in region"@en ;
    rdfs:comment "Identifies a Region in which a ContentRating is valid."@en ;
    rdfs:domain :ContentRating ;
    rdfs:range :Region .

:AgeCategory a owl:Class ;
    rdfs:label "Age Category"@en ;
    rdfs:comment "A SKOS concept representing an age category in a rating system."@en ;
    rdfs:subClassOf skos:Concept .

:ArtGame a owl:Class ;
    rdfs:label "Art Game"@en ;
    rdfs:comment "A type of video game."@en ;
    rdfs:subClassOf :VideoGame .

:Australia a :Region ;
    rdfs:label "Australia"@en .

:ContentDescriptor a owl:Class ;
    rdfs:label "Content Descriptor"@en ;
    rdfs:comment "A SKOS concept describing content reflected in a content rating."@en ;
    rdfs:subClassOf skos:Concept .

:DigitalCamera a owl:Class ;
    rdfs:label "Digital Camera"@en ;
    rdfs:comment "A type of input device."@en ;
    rdfs:subClassOf :InputDevice .

:DisplayTechnology a owl:Class ;
    rdfs:label "Display Technology"@en ;
    rdfs:comment "A controlled concept for a display technology supported by a game or release."@en ;
    rdfs:subClassOf skos:Concept .

:GameCube a :HomeConsole ;
    rdfs:label "GameCube"@en .

:GameplayMechanic a owl:Class ;
    rdfs:label "Gameplay Mechanic"@en ;
    rdfs:comment "A controlled concept for a gameplay rule, system, or mechanic."@en ;
    rdfs:subClassOf skos:Concept .

:Genre a owl:Class ;
    rdfs:label "Genre"@en ;
    rdfs:comment "A SKOS concept used to classify a VideoGame by genre. Genre taxonomies should use skos:broader/skos:narrower (and scope/history notes when useful) rather than duplicating genre names as OWL subclasses."@en ;
    rdfs:subClassOf skos:Concept .

:Germany a :Region ;
    rdfs:label "Germany"@en .

:HandheldConsole a owl:Class ;
    rdfs:label "Handheld Console"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:HistoricalPeriod a owl:Class ;
    rdfs:label "Historical Period"@en ;
    rdfs:comment "A named historical period modeled as both a Dublin Core period of time and an OWL-Time interval; represent boundaries with time:hasBeginning/time:hasEnd and time:Instant resources."@en ;
    rdfs:subClassOf dcterms:PeriodOfTime,
        time:Interval .

:Japan a :Region ;
    rdfs:label "Japan"@en .

:Microphone a owl:Class ;
    rdfs:label "Microphone"@en ;
    rdfs:comment "A type of input device."@en ;
    rdfs:subClassOf :InputDevice .

:Mod a owl:Class ;
    rdfs:label "Mod"@en ;
    rdfs:comment "A GameExtension that modifies at least one GameResource; :modifiesResource also specializes :extendsResource."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :modifiesResource ;
            owl:someValuesFrom :GameResource ],
        :GameExtension .

:Nintendo a :Organization ;
    rdfs:label "Nintendo"@en .

:PlayStation a :HomeConsole ;
    rdfs:label "PlayStation"@en .

:Port a owl:Class ;
    rdfs:label "Port"@en ;
    rdfs:comment "A game release adapted to run on a platform or technical environment different from an earlier release."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :portOf ;
            owl:someValuesFrom :GameRelease ],
        :GameRelease .

:ProvenanceRecord a owl:Class ;
    rdfs:label "Provenance Record"@en ;
    rdfs:comment "A PROV entity used to group provenance assertions for a resource; it may cite derivation sources, attribution agents, and generation time using PROV-O properties."@en ;
    rdfs:subClassOf prov:Entity .

:RatingAuthority a owl:Class ;
    rdfs:label "Rating Authority"@en ;
    rdfs:comment "An organization that administers a content-rating system."@en ;
    rdfs:subClassOf :Organization .

:Remake a owl:Class ;
    rdfs:label "Remake"@en ;
    rdfs:comment "A game release that recreates an earlier game release as a new derived release."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :remakeOf ;
            owl:someValuesFrom :GameRelease ],
        :GameRelease .

:Remaster a owl:Class ;
    rdfs:label "Remaster"@en ;
    rdfs:comment "A game release derived from an earlier release with revised presentation or technical treatment while substantially preserving the original game."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :remasterOf ;
            owl:someValuesFrom :GameRelease ],
        :GameRelease .

:Spacewar a :VideoGame ;
    rdfs:label "Spacewar!"@en .

:UnitedKingdom a :Region ;
    rdfs:label "United Kingdom"@en .

:UnitedStates a :Region ;
    rdfs:label "United States"@en .

:VRInputDevice a owl:Class ;
    rdfs:label "VR input device"@en ;
    rdfs:comment "A type of input device."@en ;
    rdfs:subClassOf :InputDevice .

:VROutputDevice a owl:Class ;
    rdfs:label "VR output device"@en ;
    rdfs:comment "A type of output device."@en ;
    rdfs:subClassOf :OutputDevice .

:VideoGameSeries a owl:Class ;
    rdfs:label "Video Game Series"@en ;
    rdfs:comment "A creative-work series to which one or more VideoGame resources belong."@en ;
    rdfs:subClassOf schema:CreativeWorkSeries .

:Webcam a owl:Class ;
    rdfs:label "Webcam"@en ;
    rdfs:comment "A DigitalCamera used as an input device for live video capture, communication, streaming, or gameplay-related sensing."@en ;
    rdfs:subClassOf :DigitalCamera .

:accessibleViaOnlineService a owl:ObjectProperty ;
    rdfs:label "accessible via online service"@en ;
    rdfs:comment "Indicates an online service through which a GameResource can be accessed."@en ;
    rdfs:domain :GameResource ;
    rdfs:range :OnlineService .

:associatedWithGame a owl:ObjectProperty ;
    rdfs:label "associated with game"@en ;
    rdfs:comment "Links game-related content to the VideoGame with which it is associated. For a GameExtension that extends a GameRelease, the association can be inferred through :extendsResource followed by :releaseOf."@en ;
    rdfs:domain :GameRelatedContent ;
    rdfs:range :VideoGame ;
    owl:propertyChainAxiom ( :extendsResource :releaseOf ) .

:exclusiveToPlatform a owl:ObjectProperty ;
    rdfs:label "exclusive to platform"@en ;
    rdfs:comment "Indicates a Platform to which a GameRelease is exclusive; this is a specialization of :availableOnPlatform."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :Platform ;
    rdfs:subPropertyOf :availableOnPlatform .

:featuresGameRelease a owl:ObjectProperty ;
    rdfs:label "features game release"@en ;
    rdfs:comment "Identifies a particular GameRelease featured in a CompetitiveContext."@en ;
    rdfs:domain :CompetitiveContext ;
    rdfs:range :GameRelease .

:hasPlatformHolder a owl:ObjectProperty ;
    rdfs:label "has platform holder"@en ;
    rdfs:comment "Identifies the Organization that holds or controls a Platform."@en ;
    rdfs:domain :Platform ;
    rdfs:range :Organization .

:issuedByRatingSystem a owl:ObjectProperty ;
    rdfs:label "issued by rating system"@en ;
    rdfs:comment "Identifies the RatingSystem that issued a ContentRating."@en ;
    rdfs:domain :ContentRating ;
    rdfs:range :RatingSystem .

:modifiesResource a owl:ObjectProperty ;
    rdfs:label "modifies resource"@en ;
    rdfs:comment "Identifies the GameResource modified by a Mod. Because Mod is a GameExtension, this relation specializes :extendsResource."@en ;
    rdfs:domain :Mod ;
    rdfs:range :GameResource ;
    rdfs:subPropertyOf :extendsResource .

:portOf a owl:ObjectProperty ;
    rdfs:label "port of"@en ;
    rdfs:comment "Identifies the earlier GameRelease from which a Port was derived."@en ;
    rdfs:domain :Port ;
    rdfs:range :GameRelease ;
    rdfs:subPropertyOf prov:wasDerivedFrom .

:remakeOf a owl:ObjectProperty ;
    rdfs:label "remake of"@en ;
    rdfs:comment "Identifies the earlier GameRelease from which a Remake was derived."@en ;
    rdfs:domain :Remake ;
    rdfs:range :GameRelease ;
    rdfs:subPropertyOf prov:wasDerivedFrom .

:remasterOf a owl:ObjectProperty ;
    rdfs:label "remaster of"@en ;
    rdfs:comment "Identifies the earlier GameRelease from which a Remaster was derived."@en ;
    rdfs:domain :Remaster ;
    rdfs:range :GameRelease ;
    rdfs:subPropertyOf prov:wasDerivedFrom .

:usesGameRelease a owl:ObjectProperty ;
    rdfs:label "uses game release"@en ;
    rdfs:comment "Identifies the GameRelease used in a GameplaySession."@en ;
    rdfs:domain :GameplaySession ;
    rdfs:range :GameRelease ;
    rdfs:subPropertyOf prov:used .

:CasualGame a owl:Class ;
    rdfs:label "Casual Game"@en ;
    rdfs:comment "A type of video game."@en ;
    rdfs:subClassOf :VideoGame .

:CloudGamingPlatform a owl:Class ;
    rdfs:label "Cloud Gaming Platform"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:Device a owl:Class ;
    rdfs:label "Device"@en ;
    rdfs:comment "A physical or virtual device used for game input or output."@en ;
    rdfs:subClassOf prov:Entity .

:EducationalGame a owl:Class ;
    rdfs:label "Educational Game"@en ;
    rdfs:comment "A type of serious game."@en ;
    rdfs:subClassOf :SeriousGame .

:GameEngine a owl:Class ;
    rdfs:label "Game Engine"@en ;
    rdfs:comment "Software used to develop or run a video game or game release."@en ;
    rdfs:subClassOf schema:SoftwareApplication .

:MonetizationModel a owl:Class ;
    rdfs:label "Monetization Model"@en ;
    rdfs:comment "A controlled concept describing how a game or release is monetized."@en ;
    rdfs:subClassOf skos:Concept .

:OpticalDisc a owl:Class ;
    rdfs:label "Optical Disc"@en ;
    rdfs:comment "A type of physical media format."@en ;
    rdfs:subClassOf :PhysicalMediaFormat .

:UserInterface a owl:Class ;
    rdfs:label "User Interface"@en ;
    rdfs:comment "An interface through which a player receives game state information or interacts with a video game."@en .

:availableOnPlatform a owl:ObjectProperty ;
    rdfs:label "available on platform"@en ;
    rdfs:comment "Indicates a Platform on which a GameRelease is available."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :Platform ;
    rdfs:subPropertyOf schema:gamePlatform .

:supportsInputDevice a owl:ObjectProperty ;
    rdfs:label "supports input device"@en ;
    rdfs:comment "Identifies an InputDevice supported by a VideoGame or GameRelease."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :InputDevice .

:usedInputDevice a owl:ObjectProperty ;
    rdfs:label "used input device"@en ;
    rdfs:comment "Identifies an InputDevice actually used during a GameplaySession."@en ;
    rdfs:domain :GameplaySession ;
    rdfs:range :InputDevice ;
    rdfs:subPropertyOf prov:used .

:usesMediaFormat a owl:ObjectProperty ;
    rdfs:label "uses media format"@en ;
    rdfs:comment "Identifies a MediaFormat used to distribute or install a GameRelease."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :MediaFormat .

:Character a owl:Class ;
    rdfs:label "Character"@en ;
    rdfs:comment "A character appearing in a video game."@en .

:extendsResource a owl:ObjectProperty ;
    rdfs:label "extends resource"@en ;
    rdfs:comment "Identifies the GameResource extended by a GameExtension."@en ;
    rdfs:domain :GameExtension ;
    rdfs:range :GameResource .

:hasParticipatingOrganization a owl:ObjectProperty ;
    rdfs:label "has participating organization"@en ;
    rdfs:comment "Relates a VideoGame or GameRelease to an Organization participating in its development, publication, or distribution."@en ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( :VideoGame :GameRelease ) ] ;
    rdfs:range :Organization .

:releaseOf a owl:ObjectProperty ;
    rdfs:label "release of"@en ;
    rdfs:comment "Links a particular GameRelease to the VideoGame work that it releases."@en ;
    rdfs:domain :GameRelease ;
    rdfs:range :VideoGame ;
    rdfs:subPropertyOf schema:exampleOfWork .

:DistributionMethod a owl:Class ;
    rdfs:label "Distribution Method"@en ;
    rdfs:comment "A controlled concept describing how a GameRelease is delivered or distributed."@en ;
    rdfs:subClassOf skos:Concept .

:FeedbackCapability a owl:Class ;
    rdfs:label "Feedback Capability"@en ;
    rdfs:comment "A visual, audio, haptic, or other feedback capability."@en .

:GameExtension a owl:Class ;
    rdfs:label "Game Extension"@en ;
    rdfs:comment "A game-related creative resource that extends another GameResource, such as an expansion, downloadable content, or mod. Use dcterms:creator with a prov:Agent when creator attribution is recorded."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :extendsResource ;
            owl:someValuesFrom :GameResource ],
        :GameRelatedContent,
        :GameResource .

:GameMode a owl:Class ;
    rdfs:label "Game Mode"@en ;
    rdfs:comment "A controlled concept describing a mode of play supported by a game or release."@en ;
    rdfs:subClassOf skos:Concept .

:GameRelatedContent a owl:Class ;
    rdfs:label "Game-related content"@en ;
    rdfs:comment "Content associated with at least one VideoGame, including official or user-created material that is not necessarily itself a game release."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :associatedWithGame ;
            owl:someValuesFrom :VideoGame ],
        prov:Entity,
        schema:CreativeWork .

:MultiplayerConnectivityMode a owl:Class ;
    rdfs:label "Multiplayer Connectivity Mode"@en ;
    rdfs:comment "A controlled concept describing how multiplayer participants connect."@en ;
    rdfs:subClassOf skos:Concept .

:OnlineService a owl:Class ;
    rdfs:label "Online Service"@en ;
    rdfs:comment "An online service through which a GameResource can be accessed or whose availability may be required."@en ;
    rdfs:subClassOf schema:Service .

:GameplaySession a owl:Class ;
    rdfs:label "Gameplay Session"@en ;
    rdfs:comment "An occurrence of playing a particular GameRelease; modeled as a PROV activity."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :usesGameRelease ;
            owl:someValuesFrom :GameRelease ],
        prov:Activity .

:HomeConsole a owl:Class ;
    rdfs:label "Home Console"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:MediaFormat a owl:Class ;
    rdfs:label "Media Format"@en ;
    rdfs:comment "A physical or digital format used to distribute or install a game release."@en .

:OutputDevice a owl:Class ;
    rdfs:label "Output Device"@en ;
    rdfs:comment "A device used to present visual, audio, haptic, or other game output."@en ;
    rdfs:subClassOf :Device .

:PhysicalMediaFormat a owl:Class ;
    rdfs:label "Physical Media Format"@en ;
    rdfs:comment "A type of media format."@en ;
    rdfs:subClassOf :MediaFormat .

:SeriousGame a owl:Class ;
    rdfs:label "Serious Game"@en ;
    rdfs:comment "A type of video game."@en ;
    rdfs:subClassOf :VideoGame .

:CompetitiveContext a owl:Class ;
    rdfs:label "Competitive Context"@en ;
    rdfs:comment "A competitive context in which a game or release may participate."@en .

:GameController a owl:Class ;
    rdfs:label "Game Controller"@en ;
    rdfs:comment "An input device designed primarily for controlling gameplay."@en ;
    rdfs:subClassOf :InputDevice ;
    skos:altLabel "Controller"@en .

:MultiplayerStyle a owl:Class ;
    rdfs:label "Multiplayer Style"@en ;
    rdfs:comment "A controlled concept describing the structure of multiplayer play."@en ;
    rdfs:subClassOf skos:Concept .

:ContentRating a owl:Class ;
    rdfs:label "Content Rating"@en ;
    rdfs:comment "A provenance-capable content-rating assignment for a GameRelease that is issued by at least one RatingSystem; it may also carry a rating code, age category, content descriptors, and source metadata via dcterms:source."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :issuedByRatingSystem ;
            owl:someValuesFrom :RatingSystem ],
        prov:Entity .

:DisplayDevice a owl:Class ;
    rdfs:label "Display Device"@en ;
    rdfs:comment "A type of output device."@en ;
    rdfs:subClassOf :OutputDevice .

:RatingSystem a owl:Class ;
    rdfs:label "Rating System"@en ;
    rdfs:comment "A content-classification scheme that defines or issues age categories, content descriptors, and rating codes."@en ;
    rdfs:subClassOf skos:ConceptScheme .

:Region a owl:Class ;
    rdfs:label "Region"@en ;
    rdfs:comment "A geographic or market region relevant to releases, labels, rating systems, or rating validity."@en ;
    rdfs:subClassOf dcterms:Location,
        schema:Place .

:Organization a owl:Class ;
    rdfs:label "Organization"@en ;
    rdfs:comment "An organization participating in the video-game ecosystem."@en ;
    rdfs:subClassOf prov:Agent,
        schema:Organization .

:GameResource a owl:Class ;
    rdfs:label "Game Resource"@en ;
    rdfs:comment "A domain resource representing a video game, a particular game release, or an extension; modeled as a PROV entity so derivation provenance can be reused directly."@en ;
    rdfs:subClassOf prov:Entity .

:InputDevice a owl:Class ;
    rdfs:label "Input Device"@en ;
    rdfs:comment "A device used to provide input to a game or gameplay session."@en ;
    rdfs:subClassOf :Device .

:Platform a owl:Class ;
    rdfs:label "Platform"@en ;
    rdfs:comment "A hardware, software, browser, mobile, cloud, or virtual-reality platform on which games may run."@en .

:VideoGame a owl:Class ;
    rdfs:label "Video Game"@en ;
    rdfs:comment "A video game considered as a creative work independent of a particular release."@en ;
    rdfs:subClassOf :GameResource,
        schema:VideoGame ;
    owl:disjointWith :GameRelease .

:GameRelease a owl:Class ;
    rdfs:label "Game Release"@en ;
    rdfs:comment "A particular release, edition, or version of a VideoGame. Every GameRelease is related to at least one VideoGame through :releaseOf; use dcterms:title and dcterms:identifier for generic metadata, schema:version for version text, and :releaseDate for its formal release date."@en ;
    rdfs:subClassOf [ a owl:Restriction ;
            owl:onProperty :releaseOf ;
            owl:someValuesFrom :VideoGame ],
        [ a owl:Restriction ;
            owl:onProperty :availableOnPlatform ;
            owl:someValuesFrom :Platform ],
        :GameResource,
        schema:CreativeWork .

ontologies.08:
@prefix : <https://example.org/video-game-ontology#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix skosxl: <http://www.w3.org/2008/05/skos-xl#> .
@prefix time: <http://www.w3.org/2006/time#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://example.org/video-game-ontology>
    a owl:Ontology ;
    dcterms:title "Video Game Ontology"@en ;
    dcterms:description "An ontology for video games, releases, platforms, media, extensions, devices, genres, mechanics, multiplayer modes, organizations, engines, monetization, ratings, reviews, historical context, competitive contexts, provenance, external links, release windows, series, and gameplay sessions. It reuses Dublin Core Terms, PROV-O, SKOS, SKOS-XL, OWL-Time, Schema.org, RDF, RDFS, and OWL."@en ;
    rdfs:comment "SKOS and SKOS-XL are used for concepts and labels; PROV-O is used for derivation, qualified associations, agents, roles, and provenance records; OWL-Time is used for release windows; external alignment may use owl:sameAs and skos:exactMatch."@en .

#################################################################
# Classes
#################################################################

:AgeCategory a owl:Class ;
    rdfs:label "Age Category"@en ;
    rdfs:comment "A SKOS concept representing an age category in a rating system."@en ;
    rdfs:subClassOf skos:Concept .

:ArcadeSystem a owl:Class ;
    rdfs:label "Arcade System"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:ArtGame a owl:Class ;
    rdfs:label "Art Game"@en ;
    rdfs:comment "A type of video game."@en ;
    rdfs:subClassOf :VideoGame .

:AudioFeedbackCapability a owl:Class ;
    rdfs:label "Audio Feedback Capability"@en ;
    rdfs:comment "A type of feedback capability."@en ;
    rdfs:subClassOf :FeedbackCapability .

:BrowserPlatform a owl:Class ;
    rdfs:label "Browser Platform"@en ;
    rdfs:comment "A type of platform."@en ;
    rdfs:subClassOf :Platform .

:BuiltInScreen a owl:Class ;
    rdfs:label "Built In Screen"@en ;
    rdfs:comment "A type of display device."@en ;
    rdfs:subClassOf :DisplayDevice .

:CDROM a owl:Class ;
    rdfs:label "CD-ROM"@en ;
    rdfs:comment "A type of optical disc."@en ;
    rdfs:subClassOf :OpticalDisc .

